"""Measured layout assignments and paired date differences for Supplementary Fig 6."""
from figure_common import *
def draw_plate_rank(ax,ax2):
    key='supplementary_figure6';layouts=pd.read_csv(A/'plate_layout_by_gene.csv',dtype={'layout':str});names=['DYNLL1','ANAPC5','SPPL3','CAMKK2','P2RX7','P2RX4','ORAI1','HSPB8','PRKAB1','CIT'];z=layouts.set_index('gene').loc[names].reset_index();order=sorted(z.layout.unique());ax.set(xlim=(-.5,len(order)-.5),ylim=(len(names)-.5,-.5),xlabel='Plate layout repeated on R1 to R5');ax.set_xticks(range(len(order)),order);ax.set_yticks(range(len(names)),names,fontsize=7.5)
    for r in z.itertuples():
        y=names.index(r.gene);x=order.index(r.layout);color='#236A98' if r.gene=='DYNLL1' else '#C56B36' if r.gene in ['HSPB8','PRKAB1','CIT'] else '#9467A8';ax.scatter(x,y,marker='s',s=250,c=color,alpha=.18,edgecolors='none');ax.text(x,y,r.well,ha='center',va='center',fontsize=7.5)
    title='Repeated plate and well assignments';panel(ax,'E',title);register(key,'E',title,z,'10 genes with the same layout and well on all five dates','The seven named positive genes span five layouts and 25 physical plates. Same-plate pairs are not adjacent, including diagonals. Three centromeric targets are retained for context. Repeated positions limit independent artifact exclusion. All 335 assignments match released metadata.','official plate and well metadata checked against the frozen manifest')
    ax=ax2;gaps=pd.read_csv(A/'rank_gap_all_genes.csv');z=gaps[gaps.gene.ne('DYNLL1')].head(9).copy()
    for i,r in enumerate(z.itertuples()):
        a,b=r.DYNLL1_minus_gene_R4,r.DYNLL1_minus_gene_R5;ax.plot([a,b],[i,i],c='#A8B0B5',lw=1.2);ax.scatter(a,i,c=DATECOL[3],s=17,zorder=3);ax.scatter(b,i,c=DATECOL[4],s=17,zorder=3);ax.plot(r.DYNLL1_minus_gene_followup_mean,i,'|',c='#222222',ms=8,mew=1.3,zorder=4)
    ax.axvline(0,c='#555555',lw=.7);ax.set_yticks(range(len(z)),z.gene,fontsize=7.5);ax.invert_yaxis();ax.set_xlabel('DYNLL1 minus comparator alignment');handles=[Line2D([],[],marker='o',linestyle='none',color=DATECOL[3],ms=3,label='R4'),Line2D([],[],marker='o',linestyle='none',color=DATECOL[4],ms=3,label='R5'),Line2D([],[],marker='|',linestyle='none',color='#222222',ms=6,label='Mean')];ax.legend(handles=handles,ncol=3,frameon=False,loc='upper center',bbox_to_anchor=(.5,-.32),fontsize=7.5,handletextpad=.25,columnspacing=.6);title='Paired differences from leading comparators';panel(ax,'F',title);register(key,'F',title,z,'nine highest comparator means on the two follow-up dates','Points show paired R4 and R5 differences; connecting segments span the two observed dates, not confidence intervals. Black ticks show their means. The TAF15 gap changes sign between dates. Comparator ordering is descriptive and selected after outcomes were known.','all-gene paired differences and follow-up summaries')
